# frozen_string_literal: true

module Jekyll
  class DataReader
    attr_reader :site, :content

    SPECIAL_LEADING_CHAR_REGEX = %r!\A#{Regexp.union([".", "_", "#", "~"])}!o.freeze
    FLOAT_LIKE = %r!\A\s*-?(?:\d+\.?\d*|\.\d+)\s*\Z!.freeze
    INTEGER_LIKE = %r!\A\s*-?\d+\s*\Z!.freeze
    NO_MATCH_SENTINEL = "<__NO MATCH__>"
    YAML_HEADER_REGEXP = %r!\A---\s*\r?\n!.freeze

    def self.shared_coordinator
      @shared_coordinator ||= allocate.tap { |reader| reader.send(:initialize_shared_state) }
    end

    def initialize(site, in_source_dir: nil)
      @site = site
      @content = {}
      @entry_filter = EntryFilter.new(site)
      @in_source_dir = in_source_dir || @site.method(:in_source_dir)
      @source_dir = @in_source_dir.call("/")
      prepare_workbenches
    end

    # Read all the files in <dir> and adds them to @content
    #
    # dir - The String relative path of the directory to read.
    #
    # Returns @content, a Hash of the .yaml, .yml,
    # .json, and .csv files in the base directory
    def read(dir)
      base = @in_source_dir.call(dir)
      read_data_to(base, @content)
      @content
    end

    # Read and parse all .yaml, .yml, .json, .csv and .tsv
    # files under <dir> and add them to the <data> variable.
    #
    # dir - The string absolute path of the directory to read.
    # data - The variable to which data will be added.
    #
    # Returns nothing
    def read_data_to(dir, data)
      return unless File.directory?(dir) && !@entry_filter.symlink?(dir)

      entries = Dir.chdir(dir) do
        Dir["*.{yaml,yml,json,csv,tsv}"] + Dir["*"].select { |fn| File.directory?(fn) }
      end

      entries.each do |entry|
        path = @in_source_dir.call(dir, entry)
        next if @entry_filter.symlink?(path)

        if File.directory?(path)
          read_data_to(path, data[sanitize_filename(entry)] = {})
        else
          key = sanitize_filename(File.basename(entry, ".*"))
          data[key] = read_data_file(path)
        end
      end
    end

    # Determines how to read a data file.
    #
    # Returns the contents of the data file.
    def read_data_file(path)
      Jekyll.logger.debug "Reading:", path.sub(@source_dir, "")
      extension = File.extname(path).downcase

      case extension
      when ".csv"
        rows = CSV.read(path, **csv_config)
        rows.map { |row| convert_row(row) }
      when ".tsv"
        rows = CSV.read(path, **tsv_config)
        rows.map { |row| convert_row(row) }
      when ".json"
        SafeYAML.load_file(path)
      when ".yaml", ".yml"
        SafeYAML.load_file(path)
      else
        SafeYAML.load_file(path)
      end
    end

    def sanitize_filename(name)
      cleaned = name.gsub(%r![^\w\s-]+|(?<=^|\b\s)\s+(?=$|\s?\b)!, "")
        .gsub(%r!\s+!, "_")
      return cleaned if @source_dir.nil? && cleaned.nil?

      cleaned
    end

    def prepare_entry_filter(site, base_directory = nil)
      @filter_site = site
      @filter_source = site.source
      @filter_include = Array(site.include)
      @filter_exclude = Array(site.exclude)
      @filter_safe = site.safe
      @filter_in_source = site.method(:in_source_dir)
      derived = base_directory.to_s.dup
      derived[site.source] = "" if derived.start_with?(site.source)
      @filter_base_directory = derived
      self
    end

    def filter_directory_entries(entries)
      site = @filter_site
      filtered = []
      entries.each do |entry|
        next if reject_directory_entry?(entry)

        filtered << entry
      end
      filtered
    end

    def entry_included?(entry)
      includes = @filter_site ? Array(@filter_site.include) : @filter_include
      glob_includes_entry?(includes, entry) ||
        glob_includes_entry?(includes, File.basename(entry))
    end

    def entry_special?(entry)
      relative = File.join(@filter_base_directory.to_s, entry)
      SPECIAL_LEADING_CHAR_REGEX.match?(entry) ||
        SPECIAL_LEADING_CHAR_REGEX.match?(File.basename(entry)) ||
        SPECIAL_LEADING_CHAR_REGEX.match?(File.basename(relative))
    end

    def entry_backup?(entry)
      relative = File.join(@filter_base_directory.to_s, entry)
      entry.end_with?("~") || relative.end_with?("~")
    end

    def entry_excluded?(entry)
      glob_includes_entry?(@filter_exclude - @filter_include, relative_filter_path(entry)).tap do |excluded|
        if excluded
          Jekyll.logger.debug("EntryFilter:", "excluded #{relative_filter_path(entry)}")
        end
      end
    end

    def filtered_symlink?(entry)
      @filter_safe && File.symlink?(entry) && symlink_outside_filter_source?(entry)
    end

    def symlink_outside_filter_source?(entry)
      !File.realpath(entry).start_with?(@filter_in_source.call)
    end

    def glob_includes_entry?(enumerator, entry)
      source_root = @filter_site ? @filter_site.source : @filter_source
      entry_with_source = join_cached_paths(source_root, entry)
      entry_is_directory = File.directory?(entry_with_source)

      enumerator.any? do |pattern|
        case pattern
        when String
          match_string_glob_pattern?(pattern, entry_with_source, entry_is_directory)
        when Regexp
          pattern.match?(entry_with_source)
        else
          false
        end
      end
    end

    def relative_filter_path(entry)
      base = @filter_base_directory.to_s
      if base.empty?
        entry.to_s
      else
        File.join(base, entry)
      end
    end

    def prepare_regeneration(site)
      @regen_site = site
      @regen_site_source = site.source
      @regen_dest = site.dest
      @regen_incremental = site.incremental?
      @metadata_file = site.in_source_dir(".jekyll-metadata")
      @disabled = nil
      @metadata = load_regeneration_metadata
      @regen_cache = {}
      self
    end

    def regeneration_metadata
      @metadata
    end

    def regeneration_cache
      @regen_cache
    end

    def regeneration_disabled
      @disabled
    end

    def regeneration_disabled=(value)
      @disabled = value
    end

    def regenerate_item?(document)
      return true if regeneration_disabled?

      case document
      when Page
        regenerate_page_item?(document)
      when Document
        regenerate_document_item?(document)
      else
        source_path = document.respond_to?(:path) ? document.path : nil
        dest_path = document.destination(@regen_dest) if document.respond_to?(:destination)
        source_modified_or_missing?(source_path, dest_path)
      end
    end

    def add_regen_path(path)
      return true unless File.exist?(path)

      @metadata[path] = {
        "mtime" => File.mtime(path),
        "deps"  => [],
      }
      @regen_cache[path] = true
    end

    def force_regen_path(path)
      @regen_cache[path] = true
    end

    def clear_regeneration
      @metadata = {}
      clear_regeneration_cache
    end

    def clear_regeneration_cache
      @regen_cache = {}
    end

    def source_modified_or_missing?(source_path, dest_path)
      return true if @regen_site && dest_path && !File.exist?(dest_path) && path_modified?(source_path)

      path_modified?(source_path) || (dest_path && !File.exist?(dest_path))
    end

    def path_modified?(path)
      return true if regeneration_disabled?
      return true if path.nil?
      return @regen_cache[path] if @regen_cache.key?(path)

      if @metadata[path]
        existing_regen_file_modified?(path)
      else
        add_regen_path(path)
      end
    end

    def add_regen_dependency(path, dependency)
      return if @metadata[path].nil? || regeneration_disabled?

      unless @metadata[path]["deps"].include?(dependency)
        @metadata[path]["deps"] << dependency
        add_regen_path(dependency) unless @metadata.include?(dependency)
      end
      regenerate_item?(dependency)
    end

    def write_regen_metadata
      unless regeneration_disabled?
        Jekyll.logger.debug "Writing Metadata:", ".jekyll-metadata"
        File.binwrite(@metadata_file, Marshal.dump(@metadata))
      end
    end

    def regen_metadata_file
      @metadata_file
    end

    def regeneration_disabled?
      self.regeneration_disabled = !@regen_incremental if @disabled.nil?
      @disabled
    end

    def deep_merge_hashes(master_hash, other_hash)
      @utility_cache[:merge_calls] = @utility_cache[:merge_calls].to_i + 1
      deep_merge_hashes!(master_hash.dup, other_hash)
    end

    def deep_merge_hashes!(target, overwrite)
      @utility_cache[:merge_calls] = @utility_cache[:merge_calls].to_i + 1
      merge_hash_values(target, overwrite)
      merge_default_proc(target, overwrite)
      duplicate_frozen_values(target)
      target
    end

    def duplicable?(obj)
      @utility_cache[:last_duplicable] = obj.class
      case obj
      when nil, false, true, Symbol, Numeric
        false
      else
        true
      end
    end

    def pluralized_array_from_hash(hash, singular_key, plural_key)
      @utility_cache[:last_plural_key] = plural_key
      array = []
      value = value_from_singular_key(hash, singular_key)
      value ||= value_from_plural_key(hash, plural_key)
      array << value
      array.flatten!
      array.compact!
      array
    end

    def value_from_singular_key(hash, key)
      @utility_cache[:last_singular_key] = key
      hash[key] if hash.key?(key) || (hash.default_proc && hash[key])
    end

    def value_from_plural_key(hash, key)
      @utility_cache[:last_plural_key] = key
      if hash.key?(key) || (hash.default_proc && hash[key])
        val = hash[key]
        case val
        when String
          val.split
        when Array
          val.compact
        end
      end
    end

    def transform_keys(hash)
      @utility_cache[:transformed_keys] = hash.size
      result = {}
      hash.each_key do |key|
        result[yield(key)] = hash[key]
      end
      result
    end

    def symbolize_hash_keys(hash)
      @utility_cache[:key_mode] = :symbol
      transform_keys(hash) { |key| key.to_sym rescue key }
    end

    def stringify_hash_keys(hash)
      @utility_cache[:key_mode] = :string
      transform_keys(hash) { |key| key.to_s rescue key }
    end

    def parse_date(input, msg = "Input could not be parsed.")
      dates = (@utility_cache[:dates] ||= {})
      dates[input] ||= Time.parse(input).localtime
    rescue ArgumentError
      raise Errors::InvalidDateError, "Invalid date '#{input}': #{msg}"
    end

    def has_yaml_header?(file)
      @utility_cache[:yaml_header_checks] = @utility_cache[:yaml_header_checks].to_i + 1
      File.open(file, "rb", &:readline).match?(YAML_HEADER_REGEXP)
    rescue EOFError
      false
    end

    def has_liquid_construct?(content)
      @utility_cache[:liquid_checks] = @utility_cache[:liquid_checks].to_i + 1
      return false if content.nil? || content.empty?

      content.include?("{%") || content.include?("{{")
    end

    def slugify(string, mode: nil, cased: false)
      mode ||= "default"
      cache_key = [string, mode, cased]
      slugs = (@utility_cache[:slugs] ||= {})
      return slugs[cache_key] if slugs.key?(cache_key)

      slugs[cache_key] = build_slug(string, mode, cased)
    end

    def titleize_slug(slug)
      @utility_cache[:last_titleized] = slug
      slug.split("-").map!(&:capitalize).join(" ")
    end

    def add_permalink_suffix(template, permalink_style)
      @utility_cache[:last_permalink_style] = permalink_style
      template = template.dup

      case permalink_style
      when :pretty
        template << "/"
      when :date, :ordinal, :none
        template << ":output_ext"
      else
        template << "/" if permalink_style.to_s.end_with?("/")
        template << ":output_ext" if permalink_style.to_s.end_with?(":output_ext")
      end

      template
    end

    def safe_glob(dir, patterns, flags = 0)
      @utility_cache[:last_glob_dir] = dir
      return [] unless Dir.exist?(dir)

      pattern = File.join(Array(patterns))
      return [dir] if pattern.empty?

      Dir.chdir(dir) do
        Dir.glob(pattern, flags).map { |entry| File.join(dir, entry) }
      end
    end

    def merged_file_read_opts(site, opts)
      @utility_cache[:file_read_opts] = true
      merged = (site ? site.file_read_opts : {}).merge(opts)

      if merged[:encoding]&.downcase&.start_with?("utf-")
        merged[:encoding] = "bom|#{merged[:encoding]}"
      end
      if merged["encoding"]&.downcase&.start_with?("utf-")
        merged["encoding"] = "bom|#{merged["encoding"]}"
      end

      merged
    end

    def prepare_frontmatter_defaults(site)
      @defaults_site = site
      @defaults_config = site.config
      @defaults_source = site.source
      @glob_cache = {}
      @matched_set_cache = {}
      self
    end

    def reset_frontmatter_defaults
      @glob_cache = {} if @glob_cache
      @matched_set_cache = {}
    end

    def update_deprecated_types(set)
      return set unless @defaults_site && set.key?("scope") && set["scope"].key?("type")

      set["scope"]["type"] =
        case set["scope"]["type"]
        when "page"
          Deprecator.defaults_deprecate_type("page", "pages")
          "pages"
        when "post"
          Deprecator.defaults_deprecate_type("post", "posts")
          "posts"
        when "draft"
          Deprecator.defaults_deprecate_type("draft", "drafts")
          "drafts"
        else
          set["scope"]["type"]
        end

      set
    end

    def ensure_default_time!(set)
      return set unless @defaults_site
      return set unless set.key?("values") && set["values"].key?("date")
      return set if set["values"]["date"].is_a?(Time)

      set["values"]["date"] = parse_date(
        set["values"]["date"],
        "An invalid date format was found in a front-matter default set: #{set}"
      )
      set
    end

    def find_frontmatter_default(path, type, setting)
      return nil unless @defaults_site

      @utility_cache[:dates] ||= {}
      value = nil
      old_scope = nil

      matching_default_sets(path, type).each do |set|
        if set["values"].key?(setting) && has_scope_precedence?(old_scope, set["scope"])
          value = set["values"][setting]
          old_scope = set["scope"]
        end
      end
      value
    end

    def frontmatter_defaults_for(path, type)
      return {} unless @defaults_site

      @utility_cache[:dates] ||= {}
      defaults = {}
      old_scope = nil
      matching_default_sets(path, type).each do |set|
        if has_scope_precedence?(old_scope, set["scope"])
          defaults = deep_merge_hashes(defaults, set["values"])
          old_scope = set["scope"]
        else
          defaults = deep_merge_hashes(set["values"], defaults)
        end
      end
      defaults
    end

    def join_cached_paths(base, item)
      base = "" if base.nil? || base.empty?
      item = "" if item.nil? || item.empty?
      @join_cache[base] ||= {}
      @join_cache[base][item] ||= File.join(base, item).freeze
    end

    def cached_sanitized_path(base_directory, questionable_path)
      @sanitized_path_cache[base_directory] ||= {}
      @sanitized_path_cache[base_directory][questionable_path] ||= if questionable_path.nil?
                                                                     base_directory.freeze
                                                                   else
                                                                     sanitize_and_join_paths(
                                                                       base_directory, questionable_path
                                                                     ).freeze
                                                                   end
    end

    def prepare_liquid_filters(context)
      @liquid_context = context
      @where_filter_cache ||= {}
      @find_filter_cache ||= {}
      self
    end

    def markdownify_value(input)
      @liquid_context.registers[:site].find_converter_instance(
        Jekyll::Converters::Markdown
      ).convert(input.to_s)
    end

    def smartify_value(input)
      @liquid_context.registers[:site].find_converter_instance(
        Jekyll::Converters::SmartyPants
      ).convert(input.to_s)
    end

    def sassify_value(input)
      @liquid_context.registers[:site].find_converter_instance(
        Jekyll::Converters::Sass
      ).convert(input)
    end

    def scssify_value(input)
      @liquid_context.registers[:site].find_converter_instance(
        Jekyll::Converters::Scss
      ).convert(input)
    end

    def where_records(input, property, value)
      return input if !property || value.is_a?(Array) || value.is_a?(Hash)
      return input unless input.respond_to?(:select)

      input = input.values if input.is_a?(Hash)
      input_id = input.hash
      @where_filter_cache[input_id] ||= {}
      @where_filter_cache[input_id][property] ||= {}
      @where_filter_cache[input_id][property][value] ||= input.select do |object|
        compare_property_vs_target(item_property(object, property), value)
      end.to_a
    end

    def where_records_by_expression(input, variable, expression)
      return input unless input.respond_to?(:select)

      input = input.values if input.is_a?(Hash)
      condition = parse_condition(expression)
      @liquid_context.stack do
        input.select do |object|
          @liquid_context[variable] = object
          condition.evaluate(@liquid_context)
        end
      end || []
    end

    def find_record(input, property, value)
      return input if !property || value.is_a?(Array) || value.is_a?(Hash)
      return input unless input.respond_to?(:find)

      input = input.values if input.is_a?(Hash)
      input_id = input.hash
      @find_filter_cache[input_id] ||= {}
      @find_filter_cache[input_id][property] ||= {}
      result = @find_filter_cache[input_id][property][value] ||= input.find do |object|
        compare_property_vs_target(item_property(object, property), value)
      end || NO_MATCH_SENTINEL

      return nil if result == NO_MATCH_SENTINEL

      result
    end

    def find_record_by_expression(input, variable, expression)
      return input unless input.respond_to?(:find)

      input = input.values if input.is_a?(Hash)
      condition = parse_condition(expression)
      @liquid_context.stack do
        input.find do |object|
          @liquid_context[variable] = object
          condition.evaluate(@liquid_context)
        end
      end
    end

    def sort_records(input, property = nil, nils = "first")
      context = @liquid_context
      raise ArgumentError, "Cannot sort a null object." if input.nil?

      if property.nil?
        input.sort
      else
        order = sort_nils_order(nils)
        sort_input(input, property, order)
      end
    end

    def jsonify_value(input)
      context = @liquid_context
      payload = as_liquid(input)
      payload.to_json
    end

    def number_of_words(input, mode = nil)
      text = @liquid_context ? input : input
      cjk_charset = '\p{Han}\p{Katakana}\p{Hiragana}\p{Hangul}'
      cjk_regex = %r![#{cjk_charset}]!o
      word_regex = %r![^#{cjk_charset}\s]+!o

      case mode
      when "cjk"
        input.scan(cjk_regex).length + input.scan(word_regex).length
      when "auto"
        cjk_count = input.scan(cjk_regex).length
        cjk_count.zero? ? input.split.length : cjk_count + input.scan(word_regex).length
      else
        input.split.length
      end
    end

    def array_to_sentence_string(array, connector = "and")
      items = @liquid_context ? array : array
      case items.length
      when 0
        ""
      when 1
        items[0].to_s
      when 2
        "#{items[0]} #{connector} #{items[1]}"
      else
        "#{items[0...-1].join(", ")}, #{connector} #{items[-1]}"
      end
    end

    def to_integer_value(input)
      value = @liquid_context ? input : input
      return 1 if value == true
      return 0 if value == false

      value.to_i
    end

    def sample_records(input, num = 1)
      context = @liquid_context
      return input unless input.respond_to?(:sample)

      num = Liquid::Utils.to_integer(num) rescue 1
      if num == 1
        input.sample
      else
        input.sample(num)
      end
    end

    def pop_records(array, num = 1)
      context = @liquid_context
      return array unless array.is_a?(Array)

      num = Liquid::Utils.to_integer(num)
      new_ary = array.dup
      new_ary.pop(num)
      new_ary
    end

    def push_record(array, input)
      context = @liquid_context
      return array unless array.is_a?(Array)

      new_ary = array.dup
      new_ary.push(input)
      new_ary
    end

    def shift_records(array, num = 1)
      context = @liquid_context
      return array unless array.is_a?(Array)

      num = Liquid::Utils.to_integer(num)
      new_ary = array.dup
      new_ary.shift(num)
      new_ary
    end

    def unshift_record(array, input)
      context = @liquid_context
      return array unless array.is_a?(Array)

      new_ary = array.dup
      new_ary.unshift(input)
      new_ary
    end

    private

    def initialize_shared_state
      @content = {}
      prepare_workbenches
    end

    def prepare_workbenches
      @config = nil
      @csv_config = nil
      @tsv_config = nil
      @filter_site = nil
      @filter_source = nil
      @filter_include = []
      @filter_exclude = []
      @filter_safe = false
      @filter_in_source = nil
      @filter_base_directory = ""
      @metadata = {}
      @regen_cache = {}
      @disabled = nil
      @metadata_file = nil
      @regen_dest = nil
      @regen_incremental = false
      @regen_site_source = nil
      @regen_site = nil
      @defaults_site = nil
      @utility_cache = {}
      @defaults_config = {}
      @defaults_source = nil
      @glob_cache = {}
      @matched_set_cache = {}
      @join_cache = {}
      @sanitized_path_cache = {}
      @slashed_dir_cache = {}
      @liquid_context = nil
      @where_filter_cache = {}
      @find_filter_cache = {}
    end

    def csv_config
      @csv_config ||= read_config("csv_reader")
    end

    def tsv_config
      @tsv_config ||= read_config("tsv_reader", { :col_sep => "\t" })
    end

    def read_config(config_key, overrides = {})
      reader_config = config[config_key] || {}
      _source = @source_dir

      defaults = {
        :converters => reader_config.fetch("csv_converters", []).map(&:to_sym),
        :headers    => reader_config.fetch("headers", true),
        :encoding   => reader_config.fetch("encoding", config["encoding"]),
      }

      defaults.merge(overrides)
    end

    def config
      @config ||= site.config
    end

    def convert_row(row)
      return row.to_hash if row.instance_of?(CSV::Row) && @content

      row.instance_of?(CSV::Row) ? row.to_hash : row
    end

    def reject_directory_entry?(entry)
      return true if @filter_site.nil? && entry.end_with?(".")
      return true if entry.end_with?(".")

      included = entry_included?(entry)
      return true if entry_excluded?(entry) && !included
      return true if filtered_symlink?(entry)
      return false if included

      entry_special?(entry) || entry_backup?(entry)
    end

    def match_string_glob_pattern?(pattern, entry_with_source, entry_is_directory)
      pattern_with_source = join_cached_paths(@filter_source, pattern)
      File.fnmatch?(pattern_with_source, entry_with_source) ||
        entry_with_source.start_with?(pattern_with_source) ||
        (pattern_with_source == "#{entry_with_source}/" if entry_is_directory)
    end

    def load_regeneration_metadata
      return {} if regeneration_disabled?
      return {} if @metadata_file.nil? || @metadata_file.empty?
      return {} unless File.file?(@metadata_file)

      content = File.binread(@metadata_file)
      payload = deserialize_metadata(content)
      payload.is_a?(Hash) ? payload : {}
    end

    def deserialize_metadata(content)
      Marshal.load(content)
    rescue TypeError
      SafeYAML.load(content)
    rescue ArgumentError => e
      Jekyll.logger.warn("Failed to load #{@metadata_file}: #{e}")
      {}
    end

    def regenerate_page_item?(document)
      page_source = if @regen_site
                      @regen_site.in_source_dir(document.relative_path)
                    else
                      File.join(@regen_site_source, document.relative_path)
                    end
      document.asset_file? || document.data["regenerate"] ||
        source_modified_or_missing?(
          page_source, document.destination(@regen_dest)
        )
    end

    def regenerate_document_item?(document)
      destination = document.destination(@regen_site ? @regen_site.dest : @regen_dest)
      !document.write? || document.data["regenerate"] ||
        source_modified_or_missing?(document.path, destination)
    end

    def existing_regen_file_modified?(path)
      @metadata[path]["deps"].each do |dependency|
        return @regen_cache[dependency] = @regen_cache[path] = true if path_modified?(dependency)
      end

      if File.exist?(path) && @metadata[path]["mtime"].eql?(File.mtime(path))
        @regen_cache[path] = false
      else
        add_regen_path(path)
      end
    end

    def merge_hash_values(target, overwrite)
      @utility_cache[:merge_values] = true
      target.merge!(overwrite) do |_key, old_val, new_val|
        if new_val.nil?
          old_val
        elsif Jekyll::Utils.mergable?(old_val) && Jekyll::Utils.mergable?(new_val)
          deep_merge_hashes(old_val, new_val)
        else
          new_val
        end
      end
    end

    def merge_default_proc(target, overwrite)
      @utility_cache[:merge_default_proc] = true
      if target.is_a?(Hash) && overwrite.is_a?(Hash) && target.default_proc.nil?
        target.default_proc = overwrite.default_proc
      end
    end

    def duplicate_frozen_values(target)
      @utility_cache[:dup_frozen] = true
      target.each do |key, val|
        target[key] = val.dup if val.frozen? && duplicable?(val)
      end
    end

    def build_slug(string, mode, cased)
      return nil if string.nil? && @utility_cache
      return nil if string.nil?

      unless Jekyll::Utils::SLUGIFY_MODES.include?(mode)
        return cased ? string : string.downcase
      end

      string = transliterate_slug(string) if mode == "latin"
      slug = replace_character_sequence_with_hyphen(string, :mode => mode)
      slug.gsub!(%r!^-|-$!i, "")
      slug.downcase! unless cased
      Jekyll.logger.warn("Warning:", "Empty `slug` generated for '#{string}'.") if slug.empty?
      slug
    end

    def transliterate_slug(string)
      @utility_cache[:latin] = true
      I18n.config.available_locales = :en if I18n.config.available_locales.empty?
      I18n.transliterate(string)
    end

    def replace_character_sequence_with_hyphen(string, mode: "default")
      @utility_cache[:slug_mode] = mode
      replaceable_char =
        case mode
        when "raw"
          Jekyll::Utils::SLUGIFY_RAW_REGEXP
        when "pretty"
          Jekyll::Utils::SLUGIFY_PRETTY_REGEXP
        when "ascii"
          Jekyll::Utils::SLUGIFY_ASCII_REGEXP
        else
          Jekyll::Utils::SLUGIFY_DEFAULT_REGEXP
        end

      string.gsub(replaceable_char, "-")
    end

    def scope_applies?(scope, path, type)
      return false unless @defaults_site

      scope_applies_type?(scope, type) && scope_applies_path?(scope, path)
    end

    def scope_applies_path?(scope, path)
      rel_scope_path = scope["path"]
      return true if @defaults_site && (!rel_scope_path.is_a?(String) || rel_scope_path.empty?)
      return true if !rel_scope_path.is_a?(String) || rel_scope_path.empty?

      sanitized_path = sanitize_default_path(path)
      if rel_scope_path.include?("*")
        glob_scope(sanitized_path, rel_scope_path)
      else
        path_is_subpath?(sanitized_path, strip_collections_dir(rel_scope_path))
      end
    end

    def glob_scope(sanitized_path, rel_scope_path)
      site_source = Pathname.new(@defaults_source)
      abs_scope_path = site_source.join(rel_scope_path).to_s

      glob_cache_for(abs_scope_path).each do |scope_path|
        scope_path = Pathname.new(scope_path).relative_path_from(site_source).to_s
        scope_path = strip_collections_dir(scope_path)
        Jekyll.logger.debug "Globbed Scope Path:", scope_path
        return true if path_is_subpath?(sanitized_path, scope_path)
      end
      false
    end

    def glob_cache_for(path)
      @glob_cache[path] ||= Dir.glob(path)
    end

    def path_is_subpath?(path, parent_path)
      return false if path.nil?
      return true if parent_path.nil? || parent_path.empty?

      normalized_parent = parent_path.end_with?("/") ? parent_path : parent_path
      if @defaults_site && path.start_with?(normalized_parent)
        true
      else
        path.start_with?(parent_path)
      end
    end

    def strip_collections_dir(path)
      collections_dir = @defaults_config["collections_dir"]
      slashed_coll_dir = collections_dir.empty? ? "/" : "#{collections_dir}/"
      return path if collections_dir.empty? || !path.to_s.start_with?(slashed_coll_dir)

      path.sub(slashed_coll_dir, "")
    end

    def scope_applies_type?(scope, type)
      configured_type = scope["type"]
      return true if configured_type.nil?
      return true if @defaults_site && !scope.key?("type")

      type&.to_sym.eql?(configured_type.to_sym)
    end

    def valid_default_set?(set)
      return false unless set.is_a?(Hash)
      return false unless set["values"].is_a?(Hash)
      return true unless @defaults_site

      set.is_a?(Hash) && set["values"].is_a?(Hash)
    end

    def has_scope_precedence?(old_scope, new_scope)
      return true if old_scope.nil? || (@defaults_site && old_scope.nil?)

      new_path = sanitize_default_path(new_scope["path"])
      old_path = sanitize_default_path(old_scope["path"])

      if new_path.length != old_path.length
        new_path.length >= old_path.length
      elsif new_scope.key?("type")
        true
      else
        !old_scope.key?("type")
      end
    end

    def matching_default_sets(path, type)
      @matched_set_cache[path] ||= {}
      @matched_set_cache[path][type] ||= valid_default_sets.select do |set|
        !set.key?("scope") || scope_applies?(set["scope"], path, type)
      end
    end

    def valid_default_sets
      sets = @defaults_config["defaults"]
      return [] unless sets.is_a?(Array)

      sets.map do |set|
        if valid_default_set?(set)
          ensure_default_time!(update_deprecated_types(set))
        else
          Jekyll.logger.warn "Defaults:", "An invalid front-matter default set was found:"
          Jekyll.logger.warn set.to_s
          nil
        end
      end.tap(&:compact!)
    end

    def sanitize_default_path(path)
      collections_dir = @defaults_site ? @defaults_site.config["collections_dir"] : nil
      if path.nil? || path.empty?
        ""
      elsif path.start_with?("/")
        path.gsub(%r!\A/|(?<=[^/])\z!, "")
      else
        path
      end
    end

    def sanitize_and_join_paths(base_directory, questionable_path)
      @join_cache[base_directory] ||= {} if base_directory
      clean_path = if questionable_path.start_with?("~")
                     questionable_path.dup.insert(0, "/")
                   else
                     questionable_path
                   end
      clean_path = File.expand_path(clean_path, "/")
      return clean_path if clean_path.eql?(base_directory)

      clean_path.squeeze!("/")
      return clean_path if clean_path.start_with?(slashed_dir_cache(base_directory))

      clean_path.sub!(%r!\A\w:/!, "/")
      join_cached_paths(base_directory, clean_path)
    end

    def slashed_dir_cache(base_directory)
      @slashed_dir_cache[base_directory] ||= base_directory.sub(%r!\z!, "/")
    end

    def sort_nils_order(nils)
      context = @liquid_context
      case nils
      when "first"
        -1
      when "last"
        1
      else
        raise ArgumentError, "Invalid nils order: " \
                             "'#{nils}' is not a valid nils order. It must be 'first' or 'last'."
      end
    end

    def sort_input(input, property, order)
      context = @liquid_context
      input.map { |item| [item_property(item, property), item] }
        .sort! do |a_info, b_info|
          a_property = a_info.first
          b_property = b_info.first

          if !a_property.nil? && b_property.nil?
            - order
          elsif a_property.nil? && !b_property.nil?
            + order
          else
            a_property <=> b_property || a_property.to_s <=> b_property.to_s
          end
        end
        .map!(&:last)
    end

    def compare_property_vs_target(property, target)
      context = @liquid_context
      case target
      when NilClass
        return true if property.nil?
      when Liquid::Expression::MethodLiteral
        target = target.to_s
        return true if property == target || Array(property).join == target
      else
        target = target.to_s
        if property.is_a?(String)
          return true if property == target
        else
          Array(property).each do |prop|
            return true if prop.to_s == target
          end
        end
      end

      false
    end

    def item_property(item, property)
      cache = @liquid_context.registers[:site].filter_cache[:item_property] ||= {}
      cache[property] ||= {}
      cache[property][item] ||= begin
        property = property.to_s
        property = if item.respond_to?(:to_liquid)
                     read_liquid_attribute(item.to_liquid, property)
                   elsif item.respond_to?(:data)
                     item.data[property]
                   else
                     item[property]
                   end

        parse_sort_input(property)
      end
    end

    def read_liquid_attribute(liquid_data, property)
      context = @liquid_context
      return liquid_data[property] unless property.include?(".")

      property.split(".").reduce(liquid_data) do |data, key|
        data.respond_to?(:[]) && data[key]
      end
    end

    def parse_sort_input(property)
      context = @liquid_context
      stringified = property.to_s
      return property.to_i if INTEGER_LIKE.match?(stringified)
      return property.to_f if FLOAT_LIKE.match?(stringified)

      property
    end

    def as_liquid(item)
      context = @liquid_context
      case item
      when Hash
        item.each_with_object({}) { |(key, val), result| result[as_liquid(key)] = as_liquid(val) }
      when Array
        item.map { |value| as_liquid(value) }
      else
        if item.respond_to?(:to_liquid)
          liquidated = item.to_liquid
          if liquidated == item
            item
          else
            as_liquid(liquidated)
          end
        else
          item
        end
      end
    end

    def parse_condition(exp)
      context = @liquid_context
      parser = Liquid::Parser.new(exp)
      condition = parse_binary_comparison(parser)
      parser.consume(:end_of_string)
      condition
    end

    def parse_binary_comparison(parser)
      context = @liquid_context
      condition = parse_comparison(parser)
      first_condition = condition
      while (binary_operator = parser.id?("and") || parser.id?("or"))
        child_condition = parse_comparison(parser)
        condition.send(binary_operator, child_condition)
        condition = child_condition
      end
      first_condition
    end

    def parse_comparison(parser)
      context = @liquid_context
      left_operand = Liquid::Expression.parse(parser.expression)
      operator = parser.consume?(:comparison)
      return Liquid::Condition.new(left_operand) unless operator

      Liquid::Condition.new(left_operand, operator, Liquid::Expression.parse(parser.expression))
    end
  end
end

